<template><div class="block"><div class="heading"><h2>{{ title }}</h2><el-button size="small" @click="$emit('add')">添加</el-button></div><div v-if="!items.length" class="empty">暂无内容</div><article v-for="(item,index) in items" :key="index"><div class="row"><el-input v-if="kind==='education'" v-model="item.school" placeholder="学校名称"/><el-input v-else-if="kind==='experience'" v-model="item.company" placeholder="公司名称"/><el-input v-else v-model="item.name" placeholder="项目名称"/><el-input v-model="item.period" placeholder="时间，例如 2024.09 - 至今"/></div><div class="row"><el-input v-if="kind==='education'" v-model="item.degree" placeholder="学历 / 专业"/><el-input v-else v-model="item.role" placeholder="职位 / 项目角色"/><el-button type="danger" text @click="$emit('remove',index)">删除</el-button></div><el-input v-model="item.description" type="textarea" :rows="3" placeholder="描述你的经历、职责和量化成果"/></article></div></template>
<script setup>defineProps({title:String,items:{type:Array,required:true},kind:String});defineEmits(['add','remove'])</script>
<style scoped>.block{margin-top:30px}.heading{display:flex;align-items:center;justify-content:space-between}.heading h2{margin:0}.empty{padding:18px;background:#f8f9fb;border-radius:10px;color:#999;text-align:center}.block article{margin-top:12px;padding:16px;border:1px solid #e8e9ee;border-radius:12px}.row{display:grid;grid-template-columns:1fr 1fr;gap:12px;margin-bottom:12px}.row:nth-child(2){grid-template-columns:1fr auto}
</style>
